<?php $pageTitle='Volunteer'; require 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$conn->prepare('INSERT INTO volunteers(full_name,phone,email,skills,availability,message) VALUES(?,?,?,?,?,?)'); $s->bind_param('ssssss',$_POST['full_name'],$_POST['phone'],$_POST['email'],$_POST['skills'],$_POST['availability'],$_POST['message']); $msg=$s->execute()?'Volunteer interest submitted. Thank you.':'Unable to submit.'; } include 'header.php'; ?><section class="page-head"><div class="container"><div class="eyebrow">GET INVOLVED</div><h1>Volunteer with PACPET</h1></div></section><section class="section"><div class="container form"><p>Share your skills and availability. A PACPET coordinator can follow up.</p><?php if($msg): ?><div class="flash"><?=e($msg)?></div><?php endif; ?><form method="post"><div class="form-grid"><div><label>Full Name *</label><input name="full_name" required></div><div><label>Phone *</label><input name="phone" required></div><div><label>Email</label><input type="email" name="email"></div><div><label>Availability</label><select name="availability"><option>Weekends</option><option>Weekdays</option><option>Flexible</option><option>Occasional</option></select></div><div class="full"><label>Skills / Experience</label><textarea name="skills" placeholder="Teaching, English, photography, IT, events, etc."></textarea></div><div class="full"><label>Message</label><textarea name="message"></textarea></div></div><button class="btn">Submit Volunteer Interest</button></form></div></section><?php include 'footer.php'; ?>
